rows=[0,1,2,8,10,11,13,15]
ang=np.radians(140); d=np.array([np.cos(ang),np.sin(ang)])
def dec(z,cc,g):
    xk=z.clone(); B=len(z)
    for k in range(20):
        tk=1-k/20; tt=torch.full((B,),tk)
        v,_=net.velocity(xk,tt,cc)
        if g is not None:
            th,alpha,tan,k0,k1,cthr=g
            if k0<=k<k1:
                m=(cc<cthr).float()
                s=torch.relu(xk@torch.tensor(d,dtype=torch.float32)-th*(1-tk))
                v=v - m[:,None]*alpha*s[:,None]*torch.tensor(tan,dtype=torch.float32)[None]
        xk=xk-v/20
    return xk
